"""Generational Flavor Mixing & CKM Democratic Obstruction in D=32 Trigintaduonions.

Requirement implementation for Open Problem OP-056:
"Compute whether the unitary rotation matrix generated by the 512 two-step
transition paths through the doubling pole (f, 8) reproduces the Cabibbo angle
sin theta_C ~ 0.225 and neutrino PMNS matrix parameters.
Falsification: A computed CKM transition matrix whose eigenvalues deviate from
experimental quark mixing parameters by > 5%."

Mathematical Formulation:
1. 3-Generations Fano Fibration (HYP-063):
   In each of the 7 biregular sectors chi = f ^^^ 8 in {9..15} of T_{32},
   the 48 low-degree (degree-8) zero-divisor vertices canonically decompose
   into exactly 3 generations G_1, G_2, G_3 of 16 vertices each, indexed by
   the 3 lines of PG(2, 2) passing through root f.

2. Universal Pole Hub Mediation (512-Path Quantization):
   Cross-generational transitions are mediated exclusively in 2 steps through the
   8-vertex Pole hub P = {(f, 8), (8, f)} x 4 signs of degree 24.
   Each vertex in G_a connects to 4 Pole vertices; each Pole vertex connects to
   8 vertices in G_b.
   The total 2-step paths between ANY two generations G_a and G_b is identically:
       N(G_a -> P -> G_b) = 16 * 4 * 8 = 512 = 2^9 paths.

3. Democratic Transition Operator & S_3 Permutation Isotropy:
   Because N(G_a -> G_b) = 512 for all a, b in {1, 2, 3}, the generation-level
   transition matrix is strictly democratic:
       T_gen = 512 * J_3 = 512 * [[1, 1, 1], [1, 1, 1], [1, 1, 1]].
   Normalized probability matrix:
       P_gen = (1/3) * J_3.

4. CKM Falsification & Obstruction Theorem:
   The democratic transition enforces equal off-diagonal transition amplitudes
   |V_{12}| = |V_{23}| = |V_{13}| = 1 / sqrt(3) ~ 0.5774 (or tri-bimaximal).
   Comparing against experimental CKM quark mixing parameters:
       - |V_us|: |0.5774 - 0.2243| / 0.2243 ~ 157.4% >> 5%
       - |V_cb|: |0.5774 - 0.0422| / 0.0422 ~ 1268% >> 5%
       - |V_ub|: |0.5774 - 0.00394| / 0.00394 ~ 14555% >> 5%
   All off-diagonal elements deviate by orders of magnitude from experimental CKM values,
   rigorously satisfying the OP-056 falsification criterion (> 5% deviation) and
   proving that unperturbed 2-step pole transition paths cannot generate hierarchical
   quark mixing without generational symmetry-breaking perturbations.

5. PMNS Lepton Duality:
   In contrast to CKM, the democratic matrix J_3 naturally generates large-angle
   tri-bimaximal PMNS neutrino mixing:
       sin^2 theta_{12} = 1/3 ~ 0.333 (exp: 0.307, 8.5% agreement)
       sin^2 theta_{23} = 1/2 = 0.500 (exp: 0.546, 8.4% agreement).
"""

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Any

import networkx as nx
import numpy as np

from sedenion.cd_algebra import CDStratificationEngine
from sedenion.hydro.non_associative_fluid import fano_plane_lines


class FlavorMixingError(ValueError):
    """Raised for dimensional or algebraic errors in flavor mixing analysis."""


@dataclass(frozen=True)
class ExperimentalMixingParameters:
    """Standard Model experimental quark and lepton mixing parameters (PDG 2024)."""

    # CKM quark mixing matrix magnitudes
    v_ud: float = 0.97435
    v_us: float = 0.2243  # Cabibbo angle: sin(theta_C) ~ 0.2243
    v_ub: float = 0.00394
    v_cd: float = 0.2241
    v_cs: float = 0.9735
    v_cb: float = 0.0422
    v_td: float = 0.0086
    v_ts: float = 0.0415
    v_tb: float = 0.9991

    # PMNS neutrino mixing parameters
    sin2_theta12: float = 0.307  # Solar angle
    sin2_theta23: float = 0.546  # Atmospheric angle
    sin2_theta13: float = 0.022  # Reactor angle


class FlavorMixingAnalyzer:
    """Analyzes the 2-step pole transition paths and CKM/PMNS mixing in D=32."""

    BIREGULAR_SECTORS: tuple[int, ...] = (9, 10, 11, 12, 13, 14, 15)
    PATH_COUNT_PER_PAIR: int = 512
    ROW_SUM_PER_GENERATION: int = 32
    TOTAL_GENERATIONAL_PATHS: int = 4608  # 9 * 512

    def __init__(self, engine: CDStratificationEngine | None = None) -> None:
        self.engine = engine or CDStratificationEngine(32)
        self.fano_lines = fano_plane_lines()
        self.exp_params = ExperimentalMixingParameters()

    def get_fano_lines_for_root(self, f: int) -> list[tuple[int, int]]:
        """Find the 3 pairs (a, b) in {1..7} such that {f, a, b} is a line in PG(2, 2)."""
        pairs: list[tuple[int, int]] = []
        for line in self.fano_lines:
            if f in line:
                others = [x for x in line if x != f]
                a, b = min(others), max(others)
                if (a, b) not in pairs:
                    pairs.append((a, b))
        if len(pairs) != 3:
            raise FlavorMixingError(f"Expected 3 Fano lines through root {f}, found {len(pairs)}")
        return sorted(pairs)

    def extract_sector_generational_graph(self, chi: int) -> dict[str, Any]:
        """Extract the 3 generational blocks and Pole hub for biregular sector chi in {9..15}."""
        if chi not in self.BIREGULAR_SECTORS:
            raise FlavorMixingError(f"Sector {chi} is not in biregular range 9..15")

        f = chi ^ 8
        lines = self.get_fano_lines_for_root(f)

        g = self.engine.generate_zero_divisor_graph(target_chi=chi)
        pole_nodes = [n for n in g.nodes() if g.degree(n) == 24]
        low_nodes = [n for n in g.nodes() if g.degree(n) == 8]

        # For each line L = {f, a, b}, the 4 pairs are:
        # (a, 16 + (8+b)), (b, 16 + (8+a)), (8+a, 16 + b), (8+b, 16 + a)
        gen_pairs: dict[int, set[tuple[int, int]]] = {}
        for idx, (a, b) in enumerate(lines, start=1):
            gen_pairs[idx] = {
                (a, 16 + (8 + b)),
                (b, 16 + (8 + a)),
                (8 + a, 16 + b),
                (8 + b, 16 + a),
            }

        gen_nodes: dict[int, list[int]] = {1: [], 2: [], 3: []}
        for n in low_nodes:
            v = g.nodes[n]["vec"]
            p = tuple(sorted([v[0], v[1]]))
            for gen_idx in (1, 2, 3):
                if p in gen_pairs[gen_idx]:
                    gen_nodes[gen_idx].append(n)
                    break

        for gen_idx in (1, 2, 3):
            if len(gen_nodes[gen_idx]) != 16:
                raise FlavorMixingError(
                    f"Gen {gen_idx} in sector {chi} has {len(gen_nodes[gen_idx])} nodes, expected 16"
                )

        return {
            "graph": g,
            "pole_nodes": pole_nodes,
            "gen_nodes": gen_nodes,
            "root": f,
            "lines": lines,
        }

    def compute_2step_transition_matrices(self, chi: int = 9) -> dict[str, Any]:
        """Compute the 2-step transition matrices T_{ab} = M_a M_b^T through the Pole hub."""
        data = self.extract_sector_generational_graph(chi)
        g = data["graph"]
        pole_nodes = data["pole_nodes"]
        gen_nodes = data["gen_nodes"]

        adj = nx.to_numpy_array(g, nodelist=list(g.nodes()))
        node_to_idx = {n: i for i, n in enumerate(g.nodes())}
        pole_idx = [node_to_idx[n] for n in pole_nodes]

        # Incidence matrices M_a in {0, 1}^{16 x 8}
        M: dict[int, np.ndarray] = {}
        for a in (1, 2, 3):
            idx_a = [node_to_idx[n] for n in gen_nodes[a]]
            M[a] = adj[np.ix_(idx_a, pole_idx)]

        # Pairwise 2-step transition operators T_{ab} = M_a @ M_b.T
        T: dict[tuple[int, int], np.ndarray] = {}
        path_counts: dict[tuple[int, int], int] = {}

        for a in (1, 2, 3):
            for b in (1, 2, 3):
                T_ab = M[a] @ M[b].T
                T[(a, b)] = T_ab
                path_counts[(a, b)] = int(round(float(T_ab.sum())))

        # Generation-level transition matrix (3 x 3)
        T_gen = np.zeros((3, 3), dtype=np.int64)
        for a in range(1, 4):
            for b in range(1, 4):
                T_gen[a - 1, b - 1] = path_counts[(a, b)]

        # Normalized generational probability matrix P_gen = (1/3) * J_3
        P_gen = T_gen.astype(np.float64) / 1536.0

        return {
            "M": M,
            "T": T,
            "path_counts": path_counts,
            "T_gen": T_gen,
            "P_gen": P_gen,
            "total_paths": int(T_gen.sum()),
            "is_democratic": bool(np.all(T_gen == self.PATH_COUNT_PER_PAIR)),
        }

    def evaluate_ckm_discrepancy(self, chi: int = 9) -> dict[str, Any]:
        """Evaluate the democratic mixing predictions against experimental CKM values."""
        res = self.compute_2step_transition_matrices(chi)
        if not res["is_democratic"]:
            raise FlavorMixingError("Generational transition matrix is not democratic")

        # Theoretical democratic mixing matrix (e.g. Fourier or tri-bimaximal)
        # Off-diagonal transition amplitude is 1 / sqrt(3) ~ 0.57735
        v_pred_12 = 1.0 / math.sqrt(3.0)  # Cabibbo angle candidate
        v_pred_23 = 1.0 / math.sqrt(3.0)
        v_pred_13 = 1.0 / math.sqrt(3.0)

        # Relative errors against experimental CKM parameters: |pred - exp| / exp
        exp = self.exp_params
        err_vus = abs(v_pred_12 - exp.v_us) / exp.v_us
        err_vcb = abs(v_pred_23 - exp.v_cb) / exp.v_cb
        err_vub = abs(v_pred_13 - exp.v_ub) / exp.v_ub

        # Relative error on Cabibbo angle theta_C
        theta_c_exp = math.asin(exp.v_us)
        theta_c_pred = math.asin(min(1.0, v_pred_12))
        err_theta_c = abs(theta_c_pred - theta_c_exp) / theta_c_exp

        # Falsification check: any error > 5% (0.05)
        falsification_threshold = 0.05
        falsified = (
            err_vus > falsification_threshold
            or err_vcb > falsification_threshold
            or err_vub > falsification_threshold
        )

        return {
            "v_pred_12": v_pred_12,
            "v_exp_us": exp.v_us,
            "err_vus": err_vus,
            "err_vus_percent": err_vus * 100.0,
            "v_pred_23": v_pred_23,
            "v_exp_cb": exp.v_cb,
            "err_vcb": err_vcb,
            "err_vcb_percent": err_vcb * 100.0,
            "v_pred_13": v_pred_13,
            "v_exp_ub": exp.v_ub,
            "err_vub": err_vub,
            "err_vub_percent": err_vub * 100.0,
            "err_theta_c": err_theta_c,
            "err_theta_c_percent": err_theta_c * 100.0,
            "falsification_threshold": falsification_threshold,
            "falsified": falsified,
        }

    def evaluate_pmns_parameters(self) -> dict[str, Any]:
        """Evaluate tri-bimaximal / democratic predictions against experimental PMNS values."""
        # Tri-bimaximal PMNS:
        # sin^2(theta_12) = 1/3 ~ 0.33333
        # sin^2(theta_23) = 1/2 = 0.50000
        # sin^2(theta_13) = 0.00000
        tbm_sin2_12 = 1.0 / 3.0
        tbm_sin2_23 = 0.5
        tbm_sin2_13 = 0.0

        exp = self.exp_params
        err_12 = abs(tbm_sin2_12 - exp.sin2_theta12) / exp.sin2_theta12
        err_23 = abs(tbm_sin2_23 - exp.sin2_theta23) / exp.sin2_theta23

        return {
            "tbm_sin2_12": tbm_sin2_12,
            "exp_sin2_12": exp.sin2_theta12,
            "err_12_percent": err_12 * 100.0,
            "tbm_sin2_23": tbm_sin2_23,
            "exp_sin2_23": exp.sin2_theta23,
            "err_23_percent": err_23 * 100.0,
            "tbm_sin2_13": tbm_sin2_13,
            "exp_sin2_13": exp.sin2_theta13,
        }

    def verify_all_7_biregular_sectors(self) -> dict[int, dict[str, Any]]:
        """Verify the 512-path democratic obstruction across all 7 biregular sectors."""
        results: dict[int, dict[str, Any]] = {}
        for chi in self.BIREGULAR_SECTORS:
            trans = self.compute_2step_transition_matrices(chi)
            ckm = self.evaluate_ckm_discrepancy(chi)
            results[chi] = {
                "total_paths": trans["total_paths"],
                "is_democratic": trans["is_democratic"],
                "err_vus_percent": ckm["err_vus_percent"],
                "falsified": ckm["falsified"],
            }
        return results
